# sgnano test application in Ruby -- mode 2: text + RGB555 framebuffer. The status rows over the test pattern.
# The test application of the firmware (F10 in the filer). The screen mode is set once here and never changed.
# The music: WTF4CH.mid (the sample SMF) in the same folder as this script, repeated (m pauses and resumes it).
# Generated by scripts/make_testapp_rb.py (2026-10-17, the music 2026-10-18); edit that script, not this file.
# Keys: m music pause, t text on/off. q or ESC ends it.
M = Machine
MODE = 2
M.mode = MODE

# ---- text demo and status rows (src/app/status.c) ----
TA = M::TEXT_BG_TRANSPARENT
def tput(row, s, fg)                    # a row from column 2, padded to column 76 (no text of the previous frame is left)
  s = s[0, 74]
  M.text_put(2, row, s.ljust(74), M.tattr(fg, 0, TA))
end
def text_demo(help)
  M.text_clear(M::TEXT_CLEAR)           # transparent: the graphics show through
  M.text_put(2, 0, "sgnano  ABCabc012  ｱｲｳｴｵ  あいう漢字ＡＢＣ", M.tattr(15, 0, TA))
  16.times { |i| M.text_put(2 + i, 1, " ", M.tattr(0, i)) }   # the 16 colors as the background of blank cells
  M.text_put(19, 1, help[0, 59], M.tattr(7, 0, TA))
end
ROW_VIDEO = 3; ROW_FRAME = 4; ROW_SYS = 5; ROW_USB = 6; ROW_KBD = 8; ROW_ECHO = 9
ROW_MOUSE = 10; ROW_MSC = 12; ROW_PAD = 16; ROW_PADUI = 20
$echo = ""; $keys_n = 0
def status_video(v)
  tput(ROW_VIDEO, format("%-22s mode %-16s fb %-6s %d.%03dkHz %.2fHz", v[:timing], v[:mode_name], v[:fb],
                         v[:line_hz] / 1000, v[:line_hz] % 1000, v[:frame_hz]), 11)
end
def status_frame(v)
  pm = v[:pair_max]
  tput(ROW_FRAME, format("f%-8d ur%-5d st%-5d rc%-3d lt%d/%d  pair %d/%dus", v[:frames], v[:underrun], v[:fifo_stall],
                         v[:recover], v[:late_start], v[:late_render], pm[0], pm[1]), 11)
end
def status_sys(s)
  tput(ROW_SYS, format("up %ds  mem free %dK (max %dK)  ruby", s[:uptime], s[:mem_free] / 1024, s[:mem_largest] / 1024), 10)
end
def status_usb(s)
  tput(ROW_USB, format("usb dev %d hub %d  pad %d  reinit %d wedged %d", s[:usb_devices], s[:hubs], s[:pads],
                       s[:usb_reinit], s[:usb_wedged]), 10)
end
def status_kbd(s)
  l = s[:kbd_leds]
  tput(ROW_KBD, format("kbd %s %04X:%04X n=%-5d led %s%s%s", s[:keyboard] ? "ok " : "-- ", s[:kbd_vid], s[:kbd_pid], $keys_n,
                       l & 1 != 0 ? "N" : "-", l & 2 != 0 ? "C" : "-", l & 4 != 0 ? "S" : "-"), 14)
  tput(ROW_ECHO, $echo, 15)
end
def status_mouse
  m = M.mouse
  b = m[:buttons]
  tput(ROW_MOUSE, format("mouse %s  btn %s%s%s", m[:connected] ? "ok" : "--", b & 1 != 0 ? "L" : "-", b & 4 != 0 ? "M" : "-",
                         b & 2 != 0 ? "R" : "-"), 14)
  tput(ROW_MOUSE + 1, format("x %+7d  y %+7d  wheel %+5d", m[:x].clamp(-999999, 999999), m[:y].clamp(-999999, 999999),
                             m[:wheel].clamp(-999999, 999999)), 15)
end
def status_msc(k)
  d = M.storage(k)
  tput(ROW_MSC + k, d ? format("msc%d %s %s %dMB", k, d[:vendor], d[:product], d[:mb]) : "msc#{k} --", 10)
end
AXIS = %w[X Y Z Rx Ry Rz]
def status_pad(k, pd)
  if pd
    s = format("p%d %04X:%04X h%d", k, pd[:vid], pd[:pid], pd[:hat])
    pd[:axes].each_with_index { |a, i| s << format(" %s%+4d", AXIS[i], a) if a }
    n = pd[:buttons_n]
    if n > 0
      s << " "
      [n, 20].min.times { |i| s << ((pd[:buttons] >> i) & 1 == 1 ? ((i % 9) + 1).to_s : ".") }   # mruby has no Integer#[]
    end
    tput(ROW_PAD + k, s, 14)
  else
    tput(ROW_PAD + k, "p#{k} --", 14)
  end
end
$slow = 0
def status_tick                         # rows that change slowly: one a frame in turn; the frame, keyboard, mouse and pads every frame
  k = $slow % 11
  $slow += 1
  v = M.video_info; s = M.sys_info      # a Hash each, once a frame (fewer objects for the GC)
  if k == 0 then status_video(v)
  elsif k == 1 then status_sys(s)
  elsif k == 2 then status_usb(s)
  elsif k < 7 then status_msc(k - 3)
  end
  status_frame(v)
  status_kbd(s)
  status_mouse
  if s[:pads] > 0 || k >= 7 then 4.times { |p| pd = M.pad(p); status_pad(p, pd) if pd || k == 7 + p } end
end
def key_echo(c)                         # the keys typed, at the bottom of the keyboard rows
  $keys_n += 1
  $echo << (c >= 0x20 && c < 0x7F ? c.chr : ".")
  $echo = $echo[-60, 60] if $echo.size > 60
end

# ---- the keys at the bottom of the screen ----
KEY_ROW = 21                            # rows 21..27 of the terminal (the status rows end at 19, the pad row is 20)
def key_help(list)
  M.text_put(2, KEY_ROW, "-- keys " + "-" * 66, M.tattr(8, 0, TA))
  list.each_with_index do |(k, d), i|
    x = 2 + (i % 2) * 38; y = KEY_ROW + 1 + i / 2
    M.text_put(x, y, k.rjust(7), M.tattr(14, 0, TA))
    M.text_put(x + 8, y, d[0, 29], M.tattr(7, 0, TA))
  end
end

# ---- test pattern on the framebuffer (src/video/testpattern.c) ----
# upper half: 8 color bars (80 dots each). lower half: R, G, B and gray in 32 steps (120 lines each, 20 dots a step);
# CLUT4: the 16 palette colors (40 dots each) instead. A 1-dot white frame around
BARS = [[31, 31, 31], [31, 31, 0], [0, 31, 31], [0, 31, 0], [31, 0, 31], [31, 0, 0], [0, 0, 31], [0, 0, 0]]
def c8(v) = v * 255 / 31
def draw_pattern
  fb = M.fb
  bits = fb.bits_per_pixel
  if bits == 16
    col = ->(r, g, b) { M.rgb(c8(r), c8(g), c8(b)) }
    bar = BARS.map { |c| col.(*c) }
    grad = ->(band, v) { [col.(v, 0, 0), col.(0, v, 0), col.(0, 0, v), col.(v, v, v)][band] }
    border = col.(31, 31, 31)
  else
    BARS.each_with_index { |c, i| M.fb_palette(i, c8(c[0]), c8(c[1]), c8(c[2])) }
    bar = (0...8).to_a
    if bits == 8
      32.times do |v|
        M.fb_palette(8 + v, c8(v), 0, 0); M.fb_palette(40 + v, 0, c8(v), 0)
        M.fb_palette(72 + v, 0, 0, c8(v)); M.fb_palette(104 + v, c8(v), c8(v), c8(v))
      end
      M.fb_palette(136, 255, 255, 255)
      grad = ->(band, v) { 8 + band * 32 + v }
      border = 136
    else                                # CLUT4: 8..15 = 8 grays (black to white), the frame is color 0 (white)
      8.times { |i| v = c8(i * 31 / 7); M.fb_palette(8 + i, v, v, v) }
      border = 0
    end
  end
  8.times { |i| fb.fill_rect(i * 80, 0, 80, 240, bar[i]) }
  if bits == 4
    16.times { |i| fb.fill_rect(i * 40, 240, 40, 240, i) }
  else
    4.times { |band| 32.times { |v| fb.fill_rect(v * 20, 240 + band * 60, 20, 60, grad.(band, v)) } }
  end
  fb.rect(0, 0, 640, 480, border)
end

# ---- music (the sample SMF, Sound / SPEC_sound.md) ----
SONG = "WTF4CH.mid"
def music_start
  if File.exist?(SONG)
    Sound.play(SONG, true)
    puts "music: #{SONG} (#{Sound.length / 1000.0} s, repeated; m pauses)"
  else
    puts "music: #{SONG} is not in #{Dir.pwd} -- no music"
  end
rescue => e
  puts "music: #{e.class}: #{e.message}"
end
def music_key(c)
  return unless c == "m".ord && Sound.playing?
  Sound.paused? ? Sound.resume : Sound.pause
end

# ---- the pad (pad 0): what is pressed now, for the screen (2026-10-18) ----
PAD_NAMES = { M::PAD_X => "X", M::PAD_A => "A", M::PAD_B => "B", M::PAD_Y => "Y", M::PAD_LB => "LB", M::PAD_RB => "RB",
              M::PAD_LT => "LT", M::PAD_RT => "RT", M::PAD_BACK => "BACK", M::PAD_START => "START", M::PAD_LS => "LS", M::PAD_RS => "RS" }
$pad_on = false; $pad_chk = 0
def pad_line(short)
  if ($pad_chk += 1) % 30 == 1 then $pad_on = !M.pad(0).nil? end   # connected? (twice a second; M.pad makes a Hash)
  return short ? "PAD --" : "pad 0: not connected (the F310 needs the D switch)" unless $pad_on
  dx, dy = M.pad_dir(0)
  held = PAD_NAMES.select { |n, _| M.pad_button?(0, n) }.values.join(" ")
  sp = $odiv == 1 ? "1" : "1/#{$odiv}"
  return format("PAD %+d %+d %s %s", dx, dy, held, $lr_on.nil? ? "" : "V" + sp) if short
  lx, ly = M.pad_stick(0, :left); rx, ry = M.pad_stick(0, :right)
  format("pad 0: dir %+d %+d  left %+.2f %+.2f  right %+.2f %+.2f  %s%s", dx, dy, lx, ly, rx, ry, held,
         $lr_on.nil? ? "" : "  (speed #{sp})")
end
def pad_events                          # mode 0: the presses and releases to the UART log
  return unless $pad_on || ($pad_chk += 1) % 30 == 1 && ($pad_on = !M.pad(0).nil?)
  PAD_NAMES.merge(M::PAD_UP => "UP", M::PAD_DOWN => "DOWN", M::PAD_LEFT => "LEFT", M::PAD_RIGHT => "RIGHT").each do |n, name|
    puts "[testapp] pad 0 #{name} pressed" if M.pad_pressed?(0, n)
    puts "[testapp] pad 0 #{name} released" if M.pad_released?(0, n)
  end
end

# ---- main loop ----
music_start
M.text_visible = true
text_demo('m=music t=text q=quit')
4.times { |p| status_pad(p, nil) }
4.times { |k| status_msc(k) }
key_help([["m", "music pause / resume"], ["t", "text plane on / off"], ["q / ESC", "quit"]])
draw_pattern
quit = false
until quit
  while (c = M.key)
    if c == "q".ord then quit = true
    else
      music_key(c)
      key_echo(c)
      M.text_visible = !M.text_visible? if c == "t".ord
    end
  end
  status_tick
  tput(ROW_PADUI, pad_line(false), 11)
  M.vsync
end
Sound.stop
puts "bye"
